@import url('https://fonts.googleapis.com/css2?family=Great+Vibes&family=Playfair+Display:wght@400;700&display=swap');

.perspective-container {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  display: flex; justify-content: center; align-items: center;
  perspective: 1000px; pointer-events: none; z-index: 10;
}
.logo-card {
  position: relative; width: 300px; height: 300px;
  display: flex; flex-direction: column; justify-content: center; align-items: center;
  text-align: center; transform-style: preserve-3d;
  transition: transform 0.1s ease-out; pointer-events: auto;
}
.mandala-svg {
  position: absolute; width: 280px; height: 280px; z-index: 1;
  transform: translateZ(20px); animation: spin 40s linear infinite;
}
.mandala-path {
  fill: none; stroke: #d4af37; stroke-width: 1.5;
  stroke-dasharray: 2000; stroke-dashoffset: 2000;
  animation: drawPath 5s ease-in-out forwards, glowPulse 3s ease-in-out infinite alternate;
}
.brand-title {
  font-family: 'Great Vibes', cursive; color: #d4af37; font-size: 3.8rem;
  margin: 0; text-shadow: 0 0 15px rgba(212, 175, 55, 0.6); opacity: 0;
  animation: fadeInUp 1.5s ease forwards 0.5s, floatText 4s ease-in-out infinite 2s;
}
.brand-subtitle {
  font-family: 'Playfair Display', serif; color: #fceabb; font-size: 1.1rem;
  letter-spacing: 5px; margin: 5px 0 0 0; text-transform: uppercase; opacity: 0;
  animation: fadeInUpSubtitle 1.5s ease forwards 1s, floatSubtitle 4s ease-in-out infinite 2.5s;
}

@keyframes spin { 100% { transform: translateZ(20px) rotate(360deg); } }
@keyframes drawPath { to { stroke-dashoffset: 0; } }
@keyframes glowPulse { 0% { filter: drop-shadow(0 0 3px #d4af37); } 100% { filter: drop-shadow(0 0 10px #ffd700); } }
@keyframes fadeInUp { 0% { opacity: 0; transform: translateZ(50px) translateY(20px); } 100% { opacity: 1; transform: translateZ(50px) translateY(0); } }
@keyframes fadeInUpSubtitle { 0% { opacity: 0; transform: translateZ(40px) translateY(20px); } 100% { opacity: 1; transform: translateZ(40px) translateY(0); } }
@keyframes floatText { 0%, 100% { transform: translateZ(50px) translateY(0); } 50% { transform: translateZ(50px) translateY(-12px); } }
@keyframes floatSubtitle { 0%, 100% { transform: translateZ(40px) translateY(0); } 50% { transform: translateZ(40px) translateY(-8px); } }

@media (max-width: 400px) {
  .logo-card { width: 250px; height: 250px; }
  .brand-title { font-size: 3rem; }
  .brand-subtitle { font-size: 0.9rem; letter-spacing: 3px; }
  .mandala-svg { width: 230px; height: 230px; }
}

