const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:#120a05;overflow:hidden;touch-action:none;';

c.innerHTML = `
  <canvas id="mehendi-canvas" style="position:absolute;top:0;left:0;width:100%;height:100%;z-index:1;"></canvas>
  <div class="perspective-container">
      <div class="logo-card" id="logo-card">
          <svg class="mandala-svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
              <g class="mandala-path">
                  <circle cx="100" cy="100" r="12" />
                  <circle cx="100" cy="100" r="18" stroke-dasharray="2 4" />
                  <circle cx="100" cy="100" r="25" />
                  <path d="M 100 75 Q 115 50 100 30 Q 85 50 100 75" />
                  <path d="M 100 125 Q 115 150 100 170 Q 85 150 100 125" />
                  <path d="M 75 100 Q 50 85 30 100 Q 50 115 75 100" />
                  <path d="M 125 100 Q 150 85 170 100 Q 150 115 125 100" />
                  <path d="M 118 82 Q 145 60 150 50 Q 125 75 118 82" />
                  <path d="M 82 118 Q 55 140 50 150 Q 75 125 82 118" />
                  <path d="M 82 82 Q 55 60 50 50 Q 75 75 82 82" />
                  <path d="M 118 118 Q 145 140 150 150 Q 125 125 118 118" />
                  <circle cx="100" cy="100" r="85" stroke-dasharray="4 8" />
                  <circle cx="100" cy="100" r="95" />
                  <circle cx="100" cy="5" r="2" />
                  <circle cx="100" cy="195" r="2" />
                  <circle cx="5" cy="100" r="2" />
                  <circle cx="195" cy="100" r="2" />
              </g>
          </svg>
          <h1 class="brand-title">Shree Hari</h1>
          <h2 class="brand-subtitle">Mahendi Art</h2>
      </div>
  </div>
`;

const canvas = document.getElementById('mehendi-canvas');
const ctx = canvas.getContext('2d');
const logoCard = document.getElementById('logo-card');

let width, height, particles = [];
let pointer = { x: null, y: null, active: false };

function resize() {
    width = canvas.width = c.offsetWidth || window.innerWidth;
    height = canvas.height = c.offsetHeight || window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

class Particle {
    constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.size = Math.random() * 2;
        this.baseX = this.x;
        this.baseY = this.y;
        this.density = (Math.random() * 30) + 1;
    }
    update() {
        if (pointer.active && pointer.x != null) {
            let dx = pointer.x - this.x;
            let dy = pointer.y - this.y;
            let distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < 150) {
                let force = (150 - distance) / 150;
                this.x -= (dx / distance) * force * this.density;
                this.y -= (dy / distance) * force * this.density;
            } else {
                if (this.x !== this.baseX) this.x -= (this.x - this.baseX) / 10;
                if (this.y !== this.baseY) this.y -= (this.y - this.baseY) / 10;
            }
        }
    }
    draw() {
        ctx.fillStyle = 'rgba(212, 175, 55, 0.8)';
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
    }
}

for (let i = 0; i < 150; i++) particles.push(new Particle());

function handlePointerMove(e) {
    const rect = c.getBoundingClientRect();
    pointer.x = (e.clientX || (e.touches && e.touches[0].clientX)) - rect.left;
    pointer.y = (e.clientY || (e.touches && e.touches[0].clientY)) - rect.top;
    pointer.active = true;
    let xAxis = (rect.width / 2 - pointer.x) / 25;
    let yAxis = (rect.height / 2 - pointer.y) / 25;
    logoCard.style.transform = `rotateY(${xAxis}deg) rotateX(${yAxis}deg)`;
}

function handlePointerLeave() {
    pointer.active = false;
    logoCard.style.transform = `rotateY(0deg) rotateX(0deg)`;
}

c.addEventListener('mousemove', handlePointerMove);
c.addEventListener('touchmove', handlePointerMove);
c.addEventListener('mouseleave', handlePointerLeave);
c.addEventListener('touchend', handlePointerLeave);
c.addEventListener('touchstart', handlePointerMove);

function animate() {
    ctx.clearRect(0, 0, width, height);
    particles.forEach(p => { p.update(); p.draw(); });
    requestAnimationFrame(animate);
}
animate();
